import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic_export_with_header(self):
        rows = [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n1,x\r\n2,y\r\n")

    def test_one_shot_generators(self):
        rows = ({"a": i, "b": str(i)} for i in range(2))
        columns = (name for name in ["a", "b"])
        self.assertEqual(export_csv(rows, columns), "a,b\r\n0,0\r\n1,1\r\n")

    def test_missing_and_none_become_empty(self):
        rows = [{"a": None}, {"b": 3}, {}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n,\r\n,3\r\n,\r\n")

    def test_quoting_and_doubling(self):
        rows = [{"a": 'he said "hi"', "b": "x,y"}]
        self.assertEqual(
            export_csv(rows, ["a", "b"]),
            'a,b\r\n"he said ""hi""","x,y"\r\n',
        )

    def test_embedded_newlines_and_unicode_preserved(self):
        rows = [{"a": "line1\r\nline2", "b": "héllo"}]
        self.assertEqual(
            export_csv(rows, ["a", "b"]),
            'a,b\r\n"line1\r\nline2",héllo\r\n',
        )

    def test_unselected_fields_ignored(self):
        rows = [{"a": 1, "extra": "ignored"}]
        self.assertEqual(export_csv(rows, ["a"]), "a\r\n1\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a"]), "a\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1, "a"])
        with self.assertRaises(ValueError):
            export_csv([], ["a", None])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        columns = ["a"]
        export_csv(rows, columns)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(columns, ["a"])


if __name__ == "__main__":
    unittest.main()

